import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);int t = Integer.parseInt(br.readLine());while (t-- > 0) {int n = Integer.parseInt(br.readLine());String s = br.readLine();List<Integer> p = new ArrayList<>();for (int i = 0; i < n; i++) {if (s.charAt(i) == '*') {p.add(i);}}if (p.isEmpty()) {out.println(0);continue;}int k = p.size();long[] q = new long[k];for (int i = 0; i < k; i++) {q[i] = p.get(i) - i;}long median = q[k / 2];long moves = 0;for (long val : q) {moves += Math.abs(val - median);}out.println(moves);}out.flush();out.close();}}